#!/usr/bin/env python3
"""Spring-quarter shipped-orders reconciliation against the order service API.

Usage:
  recon.py DATA_DIR pages        fetch every orders page (resumable; saved under DATA_DIR/pages)
  recon.py DATA_DIR customers    fetch each customer behind a qualifying order, once
  recon.py DATA_DIR report OUT   compute the figures and write OUT

Every HTTP attempt is appended to DATA_DIR/requests.log.
"""
import http.client
import json
import os
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
PAGE_SIZE = 50
REGIONS = ("north", "south", "east", "west")
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)  # inclusive
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive, i.e. through 31 May inclusive
ORDER_FIELDS = (("id", str), ("customer_id", str), ("status", str), ("placed_at", str), ("amount_cents", int))


class Fatal(Exception):
    """A response we do not know how to handle safely: stop and inspect rather than guess."""


def utcnow():
    return datetime.now(timezone.utc)


def retry_after(headers):
    """Seconds to wait according to a Retry-After header (delta-seconds or HTTP-date), else None."""
    value = headers.get("Retry-After")
    if value is None:
        return None
    value = value.strip()
    try:
        secs = float(value)
    except ValueError:
        try:
            secs = (parsedate_to_datetime(value) - utcnow()).total_seconds()
        except (TypeError, ValueError):
            return None
    return max(secs, 0.0)


class Client:
    def __init__(self, data_dir):
        self.token = None
        self.token_uses = 0
        self.tokens_issued = 0
        self.log_file = open(os.path.join(data_dir, "requests.log"), "a", buffering=1)
        self.dumped = set()
        self.stats = Counter()

    def log(self, msg):
        line = f"{utcnow().isoformat(timespec='milliseconds')} {msg}"
        self.log_file.write(line + "\n")
        print(line, flush=True)

    def _send(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
            self.token_uses += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read()
        except urllib.error.HTTPError as err:
            return err.code, err.headers, err.read()

    def _dump_first(self, kind, status, headers, body):
        # Full detail the first time each kind of response shows up, so the behaviour is on record.
        if (kind, status) not in self.dumped:
            self.dumped.add((kind, status))
            self.log(f"  FIRST {kind} {status}: headers={dict(headers.items())} body={body[:1000]!r}")

    def refresh_token(self):
        _, data = self.request("POST", "/token", auth=False)
        token = data.get("token") if isinstance(data, dict) else None
        if not isinstance(token, str) or not token:
            raise Fatal(f"bad token response {data!r}")
        self.token, self.token_uses = token, 0
        self.tokens_issued += 1
        self.log(f"  new token {token}")

    def request(self, method, path, auth=True, accept=(200,), max_attempts=80):
        backoff = 0.5
        fresh_rejections = 0
        kind = path.split("?")[0].strip("/").split("/")[0]
        for attempt in range(1, max_attempts + 1):
            if auth and self.token is None:
                self.refresh_token()
            try:
                status, headers, body = self._send(method, path, auth)
            except (urllib.error.URLError, http.client.HTTPException, OSError) as err:
                self.stats["network-error"] += 1
                self.log(f"{method} {path} #{attempt} network error {err!r}; retry in {backoff}s")
                time.sleep(backoff)
                backoff = min(backoff * 2, 10)
                continue
            self.stats[status] += 1
            if status in accept:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.stats["bad-json"] += 1
                    self._dump_first(kind, "bad-json", headers, body)
                    self.log(f"{method} {path} #{attempt} {status} unparseable body; retry in {backoff}s")
                    time.sleep(backoff)
                    backoff = min(backoff * 2, 10)
                    continue
                if attempt > 1 or status != 200:
                    self.log(f"{method} {path} #{attempt} {status}")
                return status, data
            self._dump_first(kind, status, headers, body)
            if status == 401 and auth:
                fresh_rejections = fresh_rejections + 1 if self.token_uses <= 1 else 0
                self.log(f"{method} {path} #{attempt} 401 for {self.token} after {self.token_uses} uses; new token")
                if fresh_rejections >= 3:
                    raise Fatal("freshly issued tokens are being rejected")
                self.token = None
                continue
            if status == 429:
                wait = retry_after(headers)
                if wait is None or wait > 300:
                    raise Fatal(f"429 without a usable Retry-After: headers={dict(headers.items())} body={body!r}")
                self.log(f"{method} {path} #{attempt} 429; waiting {wait}s as instructed")
                time.sleep(wait + 0.05)
                continue
            if 500 <= status < 600:
                hinted = retry_after(headers)
                wait = backoff if hinted is None else hinted
                self.log(f"{method} {path} #{attempt} {status} body={body[:200]!r}; retry in {wait}s")
                time.sleep(wait)
                backoff = min(backoff * 2, 10)
                continue
            raise Fatal(f"{method} {path}: unexpected {status} headers={dict(headers.items())} body={body!r}")
        raise Fatal(f"{method} {path}: gave up after {max_attempts} attempts")


# ---------------------------------------------------------------- pages

def order_problems(item):
    if not isinstance(item, dict):
        return [f"item is {type(item).__name__}"]
    problems = []
    for field, typ in ORDER_FIELDS:
        value = item.get(field)
        if not isinstance(value, typ) or isinstance(value, bool):
            problems.append(f"{field}={value!r}")
    extra = set(item) - {f for f, _ in ORDER_FIELDS}
    if extra:
        problems.append(f"unexpected fields {sorted(extra)}")
    return problems


def page_problems(data, n):
    if not isinstance(data, dict):
        return [f"body is {type(data).__name__}"]
    problems = []
    if data.get("page") != n:
        problems.append(f"page={data.get('page')!r}")
    total = data.get("total_pages")
    if not isinstance(total, int) or isinstance(total, bool) or total < 1:
        problems.append(f"total_pages={total!r}")
        total = None
    items = data.get("items")
    if not isinstance(items, list):
        return problems + [f"items={items!r:.100}"]
    for i, item in enumerate(items):
        p = order_problems(item)
        if p:
            problems.append(f"item {i}: {p}")
    if total is not None:
        expected_next = f"/orders?page={n + 1}" if n < total else None
        if data.get("next") != expected_next:
            problems.append(f"next={data.get('next')!r}, expected {expected_next!r}")
        if n < total and len(items) != PAGE_SIZE:
            problems.append(f"{len(items)} items on a non-final page")
        if n == total and not 1 <= len(items) <= PAGE_SIZE:
            problems.append(f"{len(items)} items on the final page")
    return problems


def fetch_page(client, n, attempts=6):
    for attempt in range(1, attempts + 1):
        _, data = client.request("GET", f"/orders?page={n}")
        problems = page_problems(data, n)
        if not problems:
            items = data["items"]
            client.log(f"page {n}/{data['total_pages']}: {len(items)} items {items[0]['id']}..{items[-1]['id']}"
                       + (f" (valid on fetch {attempt})" if attempt > 1 else ""))
            return data
        client.stats["page-rejected"] += 1
        client.log(f"page {n} fetch {attempt} REJECTED: {problems[:6]} body={json.dumps(data)[:400]}")
    raise Fatal(f"page {n} never returned a valid body")


def cmd_pages(data_dir):
    client = Client(data_dir)
    out = os.path.join(data_dir, "pages")
    os.makedirs(out, exist_ok=True)
    n, total = 1, None
    while total is None or n <= total:
        path = os.path.join(out, f"page_{n:03d}.json")
        if os.path.exists(path):
            with open(path) as f:
                data = json.load(f)
        else:
            data = fetch_page(client, n)
            with open(path + ".tmp", "w") as f:
                json.dump(data, f)
            os.replace(path + ".tmp", path)
        if total is None:
            total = data["total_pages"]
        elif data["total_pages"] != total:
            raise Fatal(f"total_pages changed from {total} to {data['total_pages']} on page {n}")
        n += 1
    client.log(f"pages done: {total} pages; tokens issued {client.tokens_issued}; responses {dict(client.stats)}")


# ---------------------------------------------------------------- analysis

def load_listing(data_dir):
    """All listed orders in listing order: [(page, index, order)]."""
    out = os.path.join(data_dir, "pages")
    with open(os.path.join(out, "page_001.json")) as f:
        total = json.load(f)["total_pages"]
    listing = []
    for n in range(1, total + 1):
        with open(os.path.join(out, f"page_{n:03d}.json")) as f:
            data = json.load(f)
        assert data["page"] == n and data["total_pages"] == total and not page_problems(data, n)
        listing.extend((n, i, item) for i, item in enumerate(data["items"]))
    return total, listing


def dedupe(listing):
    """Keep the first listing of each order id; report the repeats and any that disagree."""
    first, repeats, conflicts = {}, [], []
    for page, i, order in listing:
        oid = order["id"]
        if oid in first:
            repeats.append((oid, first[oid][0], first[oid][1], page, i))
            if order != first[oid][2]:
                conflicts.append((oid, first[oid][2], order))
        else:
            first[oid] = (page, i, order)
    return {oid: o for oid, (_, _, o) in first.items()}, repeats, conflicts


def to_utc(stamp):
    dt = datetime.fromisoformat(stamp)
    if dt.tzinfo is None:
        raise ValueError(f"timestamp without an offset: {stamp!r}")
    return dt.astimezone(timezone.utc)


def qualifying(orders):
    """Distinct orders with status exactly 'shipped' placed in [1 Mar, 1 Jun) 2025 UTC."""
    return [o for o in orders.values()
            if o["status"] == "shipped" and RANGE_START <= to_utc(o["placed_at"]) < RANGE_END]


def discounted(amount_cents, pct):
    """amount less pct percent, rounded half up to a whole cent, in exact integer arithmetic."""
    scaled = amount_cents * (100 - pct)
    if scaled < 0:
        raise ValueError(f"negative amount {amount_cents}")
    result = (scaled + 50) // 100
    check = int((Decimal(amount_cents) * (100 - pct) / 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))
    assert result == check, (amount_cents, pct, result, check)
    return result


def customer_problems(data, cid):
    if not isinstance(data, dict):
        return [f"body is {type(data).__name__}"]
    problems = []
    if data.get("id") != cid:
        problems.append(f"id={data.get('id')!r}")
    if data.get("region") not in REGIONS:
        problems.append(f"region={data.get('region')!r}")
    pct = data.get("discount_pct")
    if not isinstance(pct, int) or isinstance(pct, bool) or not 0 <= pct <= 100:
        problems.append(f"discount_pct={pct!r}")
    return problems


def cmd_customers(data_dir):
    client = Client(data_dir)
    out = os.path.join(data_dir, "customers")
    os.makedirs(out, exist_ok=True)
    _, listing = load_listing(data_dir)
    orders, _, _ = dedupe(listing)
    needed = sorted({o["customer_id"] for o in qualifying(orders)})
    client.log(f"{len(needed)} distinct customers behind qualifying orders")
    for cid in needed:
        path = os.path.join(out, f"{cid}.json")
        if os.path.exists(path):  # already looked up: never ask twice
            continue
        for attempt in range(1, 7):
            status, data = client.request("GET", f"/customers/{urllib.parse.quote(cid, safe='')}", accept=(200, 404))
            problems = [] if status == 404 else customer_problems(data, cid)
            if not problems:
                break
            client.stats["customer-rejected"] += 1
            client.log(f"customer {cid} fetch {attempt} REJECTED: {problems} body={data!r}")
        else:
            raise Fatal(f"customer {cid} never returned a valid body")
        client.log(f"customer {cid}: {status} {data}")
        with open(path + ".tmp", "w") as f:
            json.dump({"status": status, "body": data}, f)
        os.replace(path + ".tmp", path)
    client.log(f"customers done; tokens issued {client.tokens_issued}; responses {dict(client.stats)}")


def cmd_report(data_dir, out_path):
    total_pages, listing = load_listing(data_dir)
    orders, repeats, conflicts = dedupe(listing)
    rows = qualifying(orders)

    customers = {}
    for cid in sorted({o["customer_id"] for o in rows}):
        with open(os.path.join(data_dir, "customers", f"{cid}.json")) as f:
            saved = json.load(f)
        if saved["status"] != 200:
            raise Fatal(f"qualifying orders reference unknown customer {cid}: {saved}")
        customers[cid] = saved["body"]

    by_region = {r: 0 for r in REGIONS}
    for o in rows:
        c = customers[o["customer_id"]]
        by_region[c["region"]] += discounted(o["amount_cents"], c["discount_pct"])
    total = sum(by_region.values())
    ids = [o["id"] for o in rows]
    assert len(ids) == len(set(ids))

    result = {"total_cents": total, "order_count": len(rows), "duplicates_skipped": len(repeats),
              "by_region": by_region}
    with open(out_path + ".tmp", "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    os.replace(out_path + ".tmp", out_path)

    # Diagnostics for the reply (not part of the deliverable).
    print(json.dumps(result, indent=2))
    print(f"pages={total_pages} listed={len(listing)} distinct={len(orders)} repeats={len(repeats)} "
          f"conflicting repeats={len(conflicts)}")
    for c in conflicts:
        print("  CONFLICT", c)
    print("statuses:", Counter(repr(o["status"]) for o in orders.values()))
    shapes = Counter(re.sub(r"\d", "9", o["placed_at"]) for o in orders.values())
    print("timestamp shapes:", dict(shapes))
    print("offsets:", Counter(to_utc(o["placed_at"]) and datetime.fromisoformat(o["placed_at"]).utcoffset()
                              for o in orders.values()))
    shipped = [o for o in orders.values() if o["status"] == "shipped"]
    local_in = {o["id"] for o in shipped if "2025-03-01" <= o["placed_at"][:10] <= "2025-05-31"}
    utc_in = {o["id"] for o in rows}
    print(f"shipped distinct={len(shipped)}; in range by UTC={len(utc_in)}; by local date={len(local_in)}; "
          f"only-UTC={sorted(utc_in - local_in)} only-local={sorted(local_in - utc_in)}")
    amounts = [o["amount_cents"] for o in orders.values()]
    print(f"amount_cents min={min(amounts)} max={max(amounts)}")
    print("discount_pct in use:", Counter(c["discount_pct"] for c in customers.values()))
    print("customers used:", len(customers))


def main():
    data_dir, cmd = sys.argv[1], sys.argv[2]
    try:
        if cmd == "pages":
            cmd_pages(data_dir)
        elif cmd == "customers":
            cmd_customers(data_dir)
        elif cmd == "report":
            cmd_report(data_dir, sys.argv[3])
        else:
            sys.exit(f"unknown command {cmd}")
    except Fatal as err:
        sys.exit(f"FATAL: {err}")


if __name__ == "__main__":
    main()

